import type { Metadata } from "next";
import { site } from "@/content/site";
import type { FaqItem } from "@/content/faq";

/** Social share image (1200×630), generated by scripts/brand_assets.py. */
export const ogImage = {
  url: "/brand/og-image.png",
  width: 1200,
  height: 630,
  alt: "CodeWaveTech · Digital Solutions",
};

export const absoluteUrl = (path = "/") => `${site.url}${path === "/" ? "" : path}`;

/** Builds per-page metadata: title, description, canonical and Open Graph. */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: {
  title: string;
  description: string;
  path: string;
  absoluteTitle?: boolean;
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} · ${site.name}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_IN",
      url: path,
      title: fullTitle,
      description,
      images: [ogImage],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [ogImage.url] },
  };
}

export interface Crumb {
  name: string;
  href?: string;
}

export function organizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": `${site.url}/#organization`,
    name: site.name,
    url: site.url,
    logo: {
      "@type": "ImageObject",
      url: `${site.url}/brand/logo-square.png`,
      width: 256,
      height: 256,
    },
    image: `${site.url}/brand/og-image.png`,
    description: site.description,
    email: site.email,
    areaServed: "IN",
    ...(site.sameAs.length ? { sameAs: site.sameAs } : {}),
    ...(site.address
      ? {
          address: {
            "@type": "PostalAddress",
            streetAddress: site.address.street,
            addressLocality: site.address.locality,
            addressRegion: site.address.region,
            postalCode: site.address.postalCode,
            addressCountry: "IN",
          },
        }
      : {}),
    contactPoint: site.phones.map((p) => ({
      "@type": "ContactPoint",
      contactType: "sales",
      telephone: p.href,
      email: site.email,
      areaServed: "IN",
      availableLanguage: ["English", "Hindi"],
      hoursAvailable: {
        "@type": "OpeningHoursSpecification",
        dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
        opens: "10:00",
        closes: "19:00",
      },
    })),
  };
}

export function breadcrumbJsonLd(crumbs: Crumb[], currentPath: string) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absoluteUrl(c.href ?? currentPath),
    })),
  };
}

export function faqJsonLd(items: FaqItem[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

export function serviceJsonLd(s: { title: string; intro: string; slug: string; items: string[] }) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name: s.title,
    description: s.intro,
    url: absoluteUrl(`/services/${s.slug}`),
    serviceType: s.title,
    areaServed: { "@type": "Country", name: "India" },
    provider: { "@id": `${site.url}/#organization` },
    hasOfferCatalog: {
      "@type": "OfferCatalog",
      name: s.title,
      itemListElement: s.items.map((name) => ({
        "@type": "Offer",
        itemOffered: { "@type": "Service", name },
      })),
    },
  };
}
